import{_ as i,c as o,o as r,ah as a}from"./chunks/framework.Ch_PcVtW.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART3/0/0_context_summary.md","filePath":"scripts/output/PART3/0/0_context_summary.md"}'),l={name:"scripts/output/PART3/0/0_context_summary.md"};function e(n,t,s,_,c,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇以时间轴形式梳理BMSG在2024年的重要发展，呈现公司旗下艺人和团体在演出、发行、跨国合作、综艺节目及新人选拔等方面的持续推进。Novel Core、BE:FIRST、MAZZEL、Aile The Shota等相继举办首次武道馆、巨蛋、全国巡演及大型场馆公演，BMSG POSSE推出合作作品，BE:FIRST更开启海外舞台。与此同时，BMSG发布关于音乐行业可持续发展的提言，试验减少CD生产环节塑料使用及调整特典销售方式，并启动第三项男子团体选秀「THE LAST PIECE」和chanmina制作的女子团体选秀「No No Girls」，体现其在艺人培养、行业改革与国际化布局上的多线发展。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物／术语／语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物／术语／语气风险点&quot;">​</a></h2><ul><li><strong>BMSG及相关人物、团体名称</strong>：Novel Core、SKY-HI、Aile The Shota、edhiii boi、REIKO、BE:FIRST、MAZZEL、ATEEZ、ちゃんみな等应统一采用项目既定译名或官方英文拼写。</li><li><strong>SKY-HI身份</strong>：此处既是艺人，也参与《Apartment B》企划，不宜简单译为“出演”或“主持”，应根据语境保留“参与企划”。</li><li><strong>BMSG POSSE</strong>：是由五位艺人组成的企划性组合或音乐项目，避免擅自译成固定团体名称。</li><li><strong>公演术语</strong>：「武道馆公演」「东京巨蛋」「京瓷巨蛋大阪」「arena公演」「opening act」需准确区分场馆演出、巡演和开场嘉宾。</li><li><strong>“ワンマンツアー”</strong>：建议译为“个人专场巡演”或“单独公演巡演”，避免直译为“单人巡演”。</li><li><strong>“配信”</strong>：根据发行语境译为“上线”“数字发行”或“发布”，不要一律译成“直播”。</li><li><strong>选秀项目</strong>：「THE LAST PIECE」与「No No Girls」均为节目或选拔企划名称，保留英文标题，并明确“男子团体选秀／女子团体选秀”。</li><li><strong>行业提言</strong>：「音楽業界を持続不可能にしないための提言」带有行业倡议和问题意识，需避免弱化为普通的“建议”。</li><li><strong>CD环保措施</strong>：原文强调从制造阶段减少塑料、削减随CD附送的特典，并将相应价值的商品直接销售，需保留其试验性与商业模式调整的含义。</li><li><strong>语气</strong>：本篇为客观、简洁的编年记录，不宜添加过多评价性形容词；同时保持音乐行业报道的专业感和信息密度。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>严格保留日期、演出顺序、场馆名称、发行时间及公演数量，统一使用中文日期格式。</li><li>首次出现的英文音乐术语可保留英文，并补充常用中文释义，如“opening act（开场嘉宾）”“arena（大型室内场馆）”。</li><li>作品名、节目名、巡演名和企划名建议使用中文书名号或引号，并保留官方英文标题。</li><li>“初の”“3度目となる”等次数信息必须明确译出，这是展现艺人发展阶段的重要信息。</li><li>对“全国8都市9公演”“全国5都市5公演”等数据保持原样，不要将城市数与场次数混淆。</li><li>“キャリア初の海外ステージ”应译为“职业生涯首次海外舞台”，突出其里程碑意义。</li><li>对BMSG的环保发行尝试采用中性、准确的报道语气，避免夸张为已全面改变CD商业模式。</li><li>组合名称、艺人名称及作品标题应与全书其他篇章保持统一写法。</li></ul>',6)])])}const g=i(l,[["render",e]]);export{S as __pageData,g as default};
